import { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, Vector2 } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();

  // ---------- Backdrop Gradient Plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  const uvNode = uv();
  // gradient stops from config
  const stops = (config.intent?.visualSpec?.colors?.gradientStops) ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const color0 = new Color(stops[0].hex);
  const color1 = new Color(stops[1].hex);
  const color2 = new Color(stops[2].hex);
  const mix01 = mix(vec3(color0.r, color0.g, color0.b), vec3(color1.r, color1.g, color1.b), smoothstep(stops[0].at, stops[1].at, uvNode.y));
  const finalColor = mix(mix01, vec3(color2.r, color2.g, color2.b), smoothstep(stops[1].at, stops[2].at, uvNode.y));
  backdropMat.colorNode = finalColor;
  backdropMat.transparent = false;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // ---------- Contact Shadow Ellipse ----------
  const shadowGeom = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0.07, 0.07, 0.07); // approx #0b0b10
  shadowMat.transparent = true;
  shadowMat.opacityNode = uniform(0.5);
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.2, -2.9);
  shadow.rotation.x = -Math.PI / 2;
  root.add(shadow);

  // ---------- Load Gear Mesh ----------
  const gearGroup = new Group();
  root.add(gearGroup);
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const primary = gltf.scene.clone();
    primary.scale.setScalar(1.6 / (primary.boundingBox?.max?.x - primary.boundingBox?.min?.x || 1));
    gearGroup.add(primary);
    // secondary gear
    const secondary = primary.clone();
    secondary.scale.setScalar(0.9 / (secondary.boundingBox?.max?.x - secondary.boundingBox?.min?.x || 1));
    secondary.position.set(1.15, 0.35, -0.1);
    gearGroup.add(secondary);

    // ---------- Gear Rotation Timelines ----------
    const primarySpeed = 0.08; // rad/s
    const secondarySpeed = -0.142; // rad/s
    const durPrimary = (Math.PI * 2) / primarySpeed;
    const durSecondary = (Math.PI * 2) / Math.abs(secondarySpeed);
    const tl = gsap.timeline({ repeat: -1 });
    tl.to(primary.rotation, { z: Math.PI * 2, duration: durPrimary, ease: 'none' }, 0);
    tl.to(secondary.rotation, { z: Math.PI * 2, duration: durSecondary, ease: 'none' }, 0);
    root.userData._gsapTimeline = tl;
  });

  // ---------- Jewel Pivot Sphere ----------
  const jewelGeom = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.colorNode = vec3(1, 0.1647, 0.2196); // #ff2a38
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.emissiveNode = vec3(1, 0.1647, 0.2196);
  jewelMat.emissiveIntensity = 1.8;
  const jewel = new Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);
  root.add(jewel);

  // ---------- Arbor Shafts ----------
  const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial();
  shaftMat.colorNode = vec3(0.086, 0.086, 0.114); // #16161d
  const shaftPrimary = new Mesh(shaftGeom, shaftMat);
  shaftPrimary.rotation.x = Math.PI / 2;
  root.add(shaftPrimary);
  const shaftSecondary = shaftPrimary.clone();
  shaftSecondary.position.set(1.15, 0.35, -0.1);
  root.add(shaftSecondary);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const opts = {
      fontSize: item.typography?.fontSize ?? 24,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    if (item.role === 'headline') {
      txt.position.set(0, -1.7, -2.8);
    } else {
      txt.position.set(0, -2.1, -2.8);
    }
    root.add(txt);
  });

  // ---------- Cinematic Primitives ----------
  const primitivesHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const prim = ctx.primitives[p.name];
      if (prim) {
        const handle = prim(root, p.params);
        primitivesHandles.push(handle);
      }
    });
  }

  // ---------- Event Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose materials & geometries
    backdropGeom.dispose();
    backdropMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    jewelGeom.dispose();
    jewelMat.dispose();
    shaftGeom.dispose();
    shaftMat.dispose();
    // dispose GLB resources if any (Three.js disposes on group removal)
    // kill GSAP timeline
    if (root.userData._gsapTimeline) {
      root.userData._gsapTimeline.kill();
    }
    // cleanup primitives
    primitivesHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
  };

  return root;
}
